parameters.jsCode:
const item = $input.first();

// Step 1: Extract raw text from OpenAI response
let rawText = '';
try {
  rawText = item.json.choices[0].message.content;
} catch (e) {
  rawText = '';
}

// Step 2: Strip any accidental markdown fences and parse
let parsed;
try {
  const cleaned = rawText
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {};
}

// Step 3: Allowed value sets for validation
const validSizes = ['1-10', '11-50', '51-200', '201-1000', '1000+'];
const validTypes = ['B2B', 'B2C', 'B2B2C', 'Marketplace', 'Enterprise', 'Startup', 'SMB'];
const validTemps = ['Cold', 'Warm', 'Hot'];
const validActions = ['Schedule Demo', 'Send Proposal', 'Discovery Call', 'Follow-up Email', 'Not Qualified'];

// Step 4: Parse and clamp leadScore
const rawScore = parseInt(parsed.leadScore, 10);
const leadScore = isNaN(rawScore) ? 50 : Math.min(100, Math.max(0, rawScore));

// Step 5: Derive temperature from score if AI value is missing or mismatched
function deriveTemperature(score) {
  if (score >= 80) return 'Hot';
  if (score >= 50) return 'Warm';
  return 'Cold';
}

const temperature = validTemps.includes(parsed.temperature)
  ? parsed.temperature
  : deriveTemperature(leadScore);

// Step 6: Build validated output with safe defaults for every field
const result = {
  companySummary: (typeof parsed.companySummary === 'string' && parsed.companySummary.length > 10)
    ? parsed.companySummary
    : 'Company information could not be determined. Manual research recommended.',

  industry: (typeof parsed.industry === 'string' && parsed.industry.length > 0)
    ? parsed.industry
    : 'Unknown',

  companySize: validSizes.includes(parsed.companySize)
    ? parsed.companySize
    : '11-50',

  businessType: validTypes.includes(parsed.businessType)
    ? parsed.businessType
    : 'B2B',

  leadScore,

  temperature,

  recommendedAction: validActions.includes(parsed.recommendedAction)
    ? parsed.recommendedAction
    : 'Follow-up Email',

  salesNotes: (typeof parsed.salesNotes === 'string' && parsed.salesNotes.length > 10)
    ? parsed.salesNotes
    : 'Insufficient lead data for detailed sales notes. Suggest a discovery call to qualify further.'
};

return [{ json: result }];
